EXPECTED_NIMTS_CABI_EXPORTS = """\
// Generated by headerkit

export interface NimTsCabiExports extends WebAssembly.Exports {
  readonly memory: WebAssembly.Memory;
  /** Initialize the NimTS WebAssembly runtime idempotently. */
  nimts_init(): void;
  /** Allocate zero-initialized linear memory of the given byte size. */
  nimts_alloc(size: number): number;
  /** Free a linear memory block previously allocated by nimts_alloc. */
  nimts_free(p: number): void;
  /** Allocate zero-initialized linear memory aligned to a power-of-two byte boundary. */
  nimts_alloc_aligned(size: number, alignment: number): number;
  /** Free an aligned linear memory block previously allocated by nimts_alloc_aligned. */
  nimts_free_aligned(p: number): void;
  /** Return the pointer component of the most recent packed result buffer. */
  nimts_get_last_result_ptr(): number;
  /** Return the byte/element length of the most recent packed result buffer. */
  nimts_get_last_result_len(): number;
  /** Return 1 if a Nim exception or defect occurred during the last C-ABI call, or 0 otherwise. */
  nimts_has_error(): number;
  /** Return the packed (len << 32) | ptr UTF-8 buffer for the last recorded error message. */
  nimts_get_last_error(): bigint;
  /** Clear the recorded C-ABI error flag and message buffer. */
  nimts_clear_error(): void;
  /** Release a registered ref-object handle and invoke its destructor. */
  nimts_destroy_handle(h: number): void;
  /** Advance closure iterator handle h by one step and return a packed (len << 32) | ptr result. */
  nimts_iter_next(h: number): bigint;
  /** Return 1 if closure iterator handle h has completed or been disposed, or 0 otherwise. */
  nimts_iter_finished(h: number): number;
  /** Dispose closure iterator handle h and reclaim its GC reference. */
  nimts_iter_dispose(h: number): void;
  /** Return the count of currently active object and iterator handles in the registry. */
  nimts_active_handle_count(): number;
  /** Resume a pending Nim Future from JavaScript with a result buffer or error flag. */
  nimts_resume_future(futureId: number, dataPtr: number, dataLen: number, isError: number): void;
  /** Create a new SPSC ring-buffer channel and return its channel handle ID. */
  nimts_chan_create(capacity: number): number;
  /** Non-blocking enqueue into channel chanId; returns 1 on success, 0 if full, or -1 if invalid/closed. */
  nimts_chan_send(chanId: number, dataPtr: number, dataLen: number): number;
  /** Non-blocking dequeue from channel chanId; returns packed (len << 32) | ptr or 0 if empty. */
  nimts_chan_try_recv(chanId: number): bigint;
  /** Return 1 if channel chanId is closed or invalid, or 0 if open. */
  nimts_chan_is_closed(chanId: number): number;
  /** Mark channel chanId as closed without destroying buffered items. */
  nimts_chan_close(chanId: number): void;
  /** Close channel chanId, remove it from the registry, and release its GC reference. */
  nimts_chan_destroy(chanId: number): void;
  /** Populate raw WASM memory pointers for channel chanId ring-buffer head, tail, data, and capacity. */
  nimts_chan_get_raw_ptrs(chanId: number, headPtr: number, tailPtr: number, bufPtr: number, capPtr: number): number;
  /** Module-namespaced alias for nimts_chan_send. */
  nimts_core_chan_send(chanId: number, dataPtr: number, dataLen: number): number;
  /** Module-namespaced alias for nimts_chan_try_recv. */
  nimts_core_chan_try_recv(chanId: number): bigint;
  /** Module-namespaced alias for nimts_chan_is_closed. */
  nimts_core_chan_is_closed(chanId: number): number;
  /** Module-namespaced alias for nimts_chan_close. */
  nimts_core_chan_close(chanId: number): void;
  /** Module-namespaced alias for nimts_chan_get_raw_ptrs. */
  nimts_core_chan_get_raw_ptrs(chanId: number, headPtr: number, tailPtr: number, bufPtr: number, capPtr: number): number;
}
"""

