def test_derive_interface_name_exact() -> None:
    assert derive_interface_name("nimts") == "NimTsCabiExports"
    assert derive_interface_name("") == "NimTsCabiExports"
    assert derive_interface_name("test_module") == "TestModuleCabiExports"
    assert derive_interface_name("audio-worklet") == "AudioWorkletCabiExports"
    assert derive_interface_name("123_dsp") == "Mod123DspCabiExports"


def test_extract_exportts_companion_entries_exact() -> None:
    entries = extract_exportts_companion_entries(REPO_ROOT / "tests" / "fixtures" / "test_module.nim")
    assert entries == [
        {
            "name": "addNumbers",
            "exportc": "nimts_addNumbers",
            "type": "skProc",
            "deprecated": False,
            "description": "Add two 32-bit signed integers and return their sum.",
        },
        {
            "name": "greet",
            "exportc": "nimts_greet",
            "type": "skProc",
            "deprecated": False,
            "description": "Format a greeting string for the given UTF-8 name slice.",
        },
    ]


def test_nimts_core_cabi_exports_exact_equality() -> None:
    actual = generate_cabi_dts(
        nim_source=REPO_ROOT / "src" / "nimts.nim",
        interface_name="NimTsCabiExports",
        include_memory=True,
        project_root=REPO_ROOT,
    )
    assert actual == EXPECTED_NIMTS_CABI_EXPORTS
    committed = (REPO_ROOT / "ts" / "cabi_exports.ts").read_text(encoding="utf-8")
    assert committed == EXPECTED_NIMTS_CABI_EXPORTS


def test_fixture_module_cabi_exports_exact_equality() -> None:
    core_out, fixture_out = generate_default_targets(REPO_ROOT)
    assert core_out.read_text(encoding="utf-8") == EXPECTED_NIMTS_CABI_EXPORTS
    assert fixture_out.read_text(encoding="utf-8") == EXPECTED_TEST_MODULE_CABI_EXPORTS

    actual = generate_cabi_dts(
        nim_source=REPO_ROOT / "tests" / "fixtures" / "test_module.nim",
        interface_name="TestModuleCabiExports",
        include_memory=True,
        project_root=REPO_ROOT,
    )
    assert actual == EXPECTED_TEST_MODULE_CABI_EXPORTS


def test_scalar_abi_mapping_jsdoc_deprecated_and_param_restoration(tmp_path: Path) -> None:
    nim_src = tmp_path / "synth_dsp.nim"
    nim_src.write_text(
        """\
proc synthInit*(freq: int32, gain: float64): int32 {.exportc: "nimts_synth_init", cdecl.} =
  ## Initialize synthesizer voice with frequency and gain.
  ## Returns voice slot index.
  freq

proc synthPackSlice*(inPtr: pointer, len: int32): uint64 {.exportc: "nimts_synth_pack", deprecated, cdecl.} =
  ## Pack pointer and byte length into 64-bit WebAssembly return value.
  0'u64

proc synthSetMode*(className: cstring, defaultMode: bool): int64 {.exportc: "nimts_synth_mode", cdecl.} =
  0'i64
""",
        encoding="utf-8",
    )

    header_code = """\
/* Generated by Nim Compiler */
#define NIM_INTBITS 32
N_LIB_PRIVATE N_NOCONV(void, signalHandler)(int sign_p0);
N_LIB_PRIVATE N_CDECL(NI32, nimts_synth_init)(NI32, NF64);
N_LIB_PRIVATE N_CDECL(NU64, nimts_synth_pack)(void* inPtr_p0, NI32 len_p1);
N_LIB_PRIVATE N_CDECL(NI64, nimts_synth_mode)(NCSTRING class_p0, NIM_BOOL default_p1);
N_CDECL(void, NimMain)(void);
"""

    actual_with_mem = generate_cabi_dts(
        header_code=header_code,
        nim_source=nim_src,
        interface_name="SynthDspExports",
        include_memory=True,
        include_core_sources=False,
        project_root=tmp_path,
    )
    expected_with_mem = """\
// Generated by headerkit

export interface SynthDspExports extends WebAssembly.Exports {
  readonly memory: WebAssembly.Memory;
  /**
   * Initialize synthesizer voice with frequency and gain.
   * Returns voice slot index.
   */
  nimts_synth_init(freq: number, gain: number): number;
  /**
   * Pack pointer and byte length into 64-bit WebAssembly return value.
   * @deprecated
   */
  nimts_synth_pack(inPtr: number, len: number): bigint;
  nimts_synth_mode(className: number, defaultMode: number): bigint;
}
"""
    assert actual_with_mem == expected_with_mem

    # Without Nim source enrichment, NimBackend strips _p0/_p1 and TsWasmWriter escapes TS keywords
    actual_no_nim = generate_cabi_dts(
        header_code=header_code,
        interface_name="SynthRawExports",
        include_memory=False,
        include_core_sources=False,
        project_root=tmp_path,
    )
    expected_no_nim = """\
// Generated by headerkit

export interface SynthRawExports extends WebAssembly.Exports {
  nimts_synth_init(arg0: number, arg1: number): number;
  nimts_synth_pack(inPtr: number, len: number): bigint;
  nimts_synth_mode(class_: number, default_: number): bigint;
}
"""
    assert actual_no_nim == expected_no_nim


def test_negative_controls_internal_symbols_and_missing_inputs(tmp_path: Path) -> None:
    # Negative control 1: Internal Nim compiler symbols and runtime helpers must be stripped
    noisy_header = """\
typedef N_NIMCALL_PTR(void, tyProc__abc123)(NI32 x_p0);
N_LIB_PRIVATE N_NOCONV(void, signalHandler)(int sign_p0);
N_CDECL(void, NimMain)(void);
N_CDECL(void, NimMainInner)(void);
N_CDECL(void, PreMain)(void);
N_LIB_PRIVATE N_NIMCALL(void, nimZeroMem)(void* p_p0, NI size_p1);
N_LIB_PRIVATE N_NIMCALL(void, eqdestroy_test)(void* dest_p0);
N_LIB_PRIVATE N_NIMCALL(void, nimGC_setStackBottom)(void* theStackBottom_p0);
N_LIB_PRIVATE N_CDECL(NI32, nimts_only_public)(NI32 value_p0);
"""
    cleaned = generate_cabi_dts(
        header_code=noisy_header,
        interface_name="FilteredExports",
        include_memory=False,
        include_core_sources=False,
    )
    assert cleaned == (
        "// Generated by headerkit\n\n"
        "export interface FilteredExports extends WebAssembly.Exports {\n"
        "  nimts_only_public(value: number): number;\n"
        "}\n"
    )

    # Negative control 2: Calling generate_cabi_dts with no inputs raises ValueError
    with pytest.raises(ValueError, match="One of header_code, header_path, or nim_source must be provided"):
        generate_cabi_dts(include_core_sources=False)

    # Negative control 3: Missing header_path, nim_source, or extra_nim_sources raises FileNotFoundError
    missing_header = tmp_path / "does_not_exist.h"
    with pytest.raises(FileNotFoundError, match="Header file not found"):
        generate_cabi_dts(header_path=missing_header, include_core_sources=False)

    missing_nim = tmp_path / "does_not_exist.nim"
    with pytest.raises(FileNotFoundError, match="Nim source file not found"):
        generate_cabi_dts(nim_source=missing_nim, include_core_sources=False)

    with pytest.raises(FileNotFoundError, match="Extra Nim source file not found"):
        generate_cabi_dts(
            header_code="void nimts_init(void);",
            extra_nim_sources=[missing_nim],
            include_core_sources=False,
        )

    with pytest.raises(FileNotFoundError, match="Nim source file not found"):
        compile_nim_cabi_header(missing_nim)


def test_headerkit_toml_config_loading() -> None:
    cfg = load_nimts_headerkit_config(REPO_ROOT)
    assert cfg.backend == "nim"
    assert cfg.transforms == ["doc-parser"]
    assert cfg.writers == ["ts_wasm"]
    ts_wasm_cfg = cfg.writer_options.get("ts_wasm")
    assert ts_wasm_cfg is not None
    assert ts_wasm_cfg.options == {
        "interface_name": "NimTsCabiExports",
        "include_memory": True,
    }
